<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useUserStore} from '@/stores/user'
import {scanSample} from '@/api/modules/sampleManagement'
import type {SampleScanResult,SampleShipment} from '@/types/sampleManagement'
import SampleShipmentActionDialog from './SampleShipmentActionDialog.vue'
const route=useRoute(),router=useRouter(),user=useUserStore(),code=ref(String(route.query.code||'')),data=ref<SampleScanResult>(),loading=ref(false),error=ref(''),receiving=ref<SampleShipment>()
const shipments=computed(()=>data.value?.shipments||data.value?.content||[])
let epoch=0,disposed=false
async function load(){const value=String(route.query.code||'').trim(),ticket=++epoch,auth=user.token;data.value=undefined;error.value='';if(!value){error.value='请扫描标签或输入样品码';return}loading.value=true;try{const result=await scanSample(value);if(ticket!==epoch||auth!==user.token||disposed)return;if(result.type==='identity'){const id=result.sampleIdentityId||result.identity?.sampleIdentityId;if(id){await router.replace({path:'/samples',query:{identityId:id}});return}}if(result.type==='legacy_batch'&&result.batchId){await router.replace({path:'/samples',query:{id:result.batchId}});return}data.value=result}catch(e){if(ticket===epoch&&auth===user.token)error.value=e instanceof Error?e.message:'无法读取此码，或当前账号无权查看'}finally{if(ticket===epoch)loading.value=false}}
function search(){void router.replace({path:'/sample-scan',query:{code:code.value.trim()}});if(String(route.query.code||'')===code.value.trim())void load()}
async function saved(){receiving.value=undefined;await load()}
watch(()=>route.query.code,()=>{code.value=String(route.query.code||'');void load()},{immediate:true})
watch(()=>user.token,()=>{++epoch;data.value=undefined;receiving.value=undefined;error.value='';loading.value=false})
onBeforeUnmount(()=>{disposed=true;++epoch})
</script>
<template><section class="sample-scan"><header><h1>样品扫码</h1><el-input v-model="code" size="small" clearable maxlength="80" placeholder="输入样品码" aria-label="样品码" @keyup.enter="search"/><el-button size="small" type="primary" @click="search">核对</el-button></header><div class="scan-content" v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">重试</el-button></el-alert><template v-if="data?.type==='assigned_shipments'"><h2>{{data.sampleCode}}</h2><p>仅显示分配给当前账号的本样品待收记录。</p><article v-for="shipment in shipments" :key="shipment.id" class="scan-card"><h3>{{shipment.code}} · {{shipment.name}}</h3><p>{{shipment.origin}} → {{shipment.destination}}</p><p>运单 {{shipment.dispatch?.tracking||'未填写'}} · 接收人 {{shipment.receiverName||'当前签收账号'}}</p><div v-for="row in shipment.rows" :key="row.rowId" class="scan-line"><strong>{{row.sampleCode||data.sampleCode}} · {{row.name}}</strong><span>{{row.specName}}</span><span>本单 {{row.qty??'待核对'}} 件</span></div><el-button type="primary" size="small" :disabled="shipment.totals.inTransit<=0" @click="receiving=shipment">登记本次实际签收</el-button></article><el-empty v-if="!shipments.length" description="暂无可办理的本人待收记录"/></template><p v-else-if="data">{{data.message||'当前账号没有可办理的样品记录。'}}</p></div><SampleShipmentActionDialog v-if="receiving" :shipment="receiving" action="receive" @close="receiving=undefined" @saved="saved"/></section></template>
<style scoped>.sample-scan{height:100%;min-height:0;display:flex;flex-direction:column;gap:12px;font-size:12px;min-width:0}header{display:flex;align-items:center;gap:8px;flex-wrap:wrap}h1{font-size:16px;margin:0;color:#243e5d}header .el-input{max-width:320px}h2{font-size:16px;color:#2b6db4}h3{font-size:14px;margin:0 0 8px}.scan-content{flex:1;min-height:0;overflow:auto}.scan-card{padding:14px;border:1px solid #dce5f0;border-radius:6px;background:#fff;max-width:720px;margin-bottom:12px;overflow-wrap:anywhere}.scan-card p{color:#647c99}.scan-line{display:flex;flex-direction:column;gap:4px;padding:8px 0;border-top:1px solid #e4ebf4}.scan-card>.el-button{margin-top:10px}.sample-scan :deep(.el-input__wrapper){min-height:28px;font-size:12px}</style>
